val request = StartTransactionEvent()
// Post request, then display DisplayConfirmationRequestEvent information.
// Send DisplayConfirmationEvent with the actual approve/decline decision.
when (event) {
    is DisplayConfirmationResultEvent -> recordAcknowledgement(event.status)
    is TransactionEndEvent -> completeFromTerminalStatus(event.status)
}
