ios.code:
let request = KSMStartTransactionEvent()
// Submit request; display KSMDisplayConfirmationRequestEvent information.
// Submit KSMDisplayConfirmationEvent with the actual user's decision.
if let acknowledgement = event as? KSMDisplayConfirmationResultEvent {
    recordAcknowledgement(acknowledgement) // app helper, not terminal success
} else if let terminal = event as? KSMTransactionFinishedEvent {
    completeFromTerminalStatus(terminal) // app helper
}
